    final labels={'name':'근로자명','phone':'휴대폰 번호','email':'이메일','address':'거주지 주소','vehicle':'차량번호','bank':'은행','bankAccount':'계좌번호','bankOwner':'예금주','taxEmail':'세금계산서 발행 이메일','otherRegion':'기타 활동 지역','otherEquipment':'기타 장비'};
    return form([for(final key in keys)field(key,labels[key]!,initial:text(p,key),required:!key.startsWith('other'),email:key=='email'||key=='taxEmail'),if(id=='work')...<Widget>[choices('specialties','전문 분야',DriverScreens.specialties,initial:strings(p['specialties'])),choices('regions','활동 지역',DriverScreens.regions,initial:strings(p['regions']))],if(id=='equipment')choices('equipment','보유 장비',DriverScreens.equipment,initial:strings(p['equipment'])),button('저장',()async{if(await submit((){s.requireActive();if(id=='profile'&&!RegExp(r'^0[0-9-]{8,14}$').hasMatch(value('phone')))throw StateError('휴대폰 번호 형식을 확인해 주세요.');p.addAll(values(keys));if(id=='work'){if(choiceValue('specialties').isEmpty||choiceValue('regions').isEmpty&&value('otherRegion').isEmpty)throw StateError('전문 분야와 활동 지역을 선택해 주세요.');p.addAll({'specialties':choiceValue('specialties').toList(),'regions':choiceValue('regions').toList()});}if(id=='equipment')p['equipment']=choiceValue('equipment').toList();},operation:'settings')){go('more');message('변경사항을 저장했습니다.');}})]);
  }
  Widget notificationSettings()=>stack([button('알림 권한 및 수신 설정',enablePush,secondary:true),if(pushStatus.isNotEmpty)notice(pushStatus),for(var i=0;i<4;i++)SwitchListTile(contentPadding:EdgeInsets.zero,title:Text((admin?['새 상담 접수','배차 상태 변경','기사 문의','기타 알림']:['배차 요청','배차 확정·취소','작업 상태 변경','관리자 문의'])[i]),value:(s.data['notifications'] as List)[i] as bool,onChanged:busy?null:(v)=>command('notifications/preferences',{'index':i,'enabled':v},()=>(s.data['notifications'] as List)[i]=v)),]);
  Widget chatScreen(){
    if(admin&&id.isEmpty)return stack([TextField(decoration:const InputDecoration(labelText:'기사명 검색'),onChanged:(v)=>refresh(()=>search=v)),for(final d in s.drivers.where((d)=>text(d,'name').contains(search)))menu('${text(d,'name')} · ${text(d,'status')}','chat',item:text(d,'id')),if(s.drivers.isEmpty)empty('대화할 기사가 없습니다.')]);
