  Widget exportScreen()=>stack([notice('현재 조회 조건에 해당하는 의뢰 ${filteredAdmin().length}건을 내보냅니다.'),dropdown('format','파일 형식',['CSV','XLSX'],initial:'CSV'),button('내보내기',()=>platformTask(()async{final rows=<List<String>>[['의뢰번호','고객명','연락처','주소','작업유형','상태','등록일'],for(final j in filteredAdmin())[for(final key in ['id','customer','phone','address','type','status','created'])text(j,key)]];final excel=value('format')=='XLSX';final bytes=excel?xlsxBytes(rows):Uint8List.fromList(utf8.encode('\uFEFF'+rows.map((r)=>r.map((v)=>'"${(RegExp(r'^[=+@-]').hasMatch(v)?"'$v":v).replaceAll('"','""')}"').join(',')).join('\r\n')));final name='올체크-의뢰목록.${excel?'xlsx':'csv'}';final mime=excel?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv';if(!kIsWeb&&defaultTargetPlatform==TargetPlatform.android){await _native.invokeMethod<void>('saveFile',{'name':name,'mime':mime,'bytes':bytes});}else{final box=context.findRenderObject() as RenderBox?;await SharePlus.instance.share(ShareParams(files:[XFile.fromData(bytes,mimeType:mime)],fileNameOverrides:[name],sharePositionOrigin:box==null?null:box.localToGlobal(Offset.zero)&box.size));}}))]);
