Uint8List xlsxBytes(List<List<String>> rows){
  String escape(String s)=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
  String column(int n){var result='';for(n++;n>0;n=n~/26){n--;result=String.fromCharCode(65+n%26)+result;}return result;}
  final sheet=StringBuffer('<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>');for(var i=0;i<rows.length;i++){sheet.write('<row r="${i+1}">');for(var j=0;j<rows[i].length;j++){sheet.write('<c r="${column(j)}${i+1}" t="inlineStr"><is><t xml:space="preserve">${escape(rows[i][j])}</t></is></c>');}sheet.write('</row>');}sheet.write('</sheetData></worksheet>');
  final files=<String,String>{'[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="의뢰 목록" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':sheet.toString()};
  int crc(List<int> bytes){var c=0xffffffff;for(final b in bytes){c^=b;for(var k=0;k<8;k++){c=(c>>>1)^((c&1)!=0?0xedb88320:0);}}return(c^0xffffffff)&0xffffffff;}
  final body=BytesBuilder(),central=BytesBuilder();var offset=0;for(final e in files.entries){final name=utf8.encode(e.key),data=utf8.encode(e.value),checksum=crc(data);final h=ByteData(30+name.length);h.setUint32(0,0x04034b50,Endian.little);h.setUint16(4,20,Endian.little);h.setUint16(6,0x800,Endian.little);h.setUint32(14,checksum,Endian.little);h.setUint32(18,data.length,Endian.little);h.setUint32(22,data.length,Endian.little);h.setUint16(26,name.length,Endian.little);h.buffer.asUint8List().setRange(30,30+name.length,name);body.add(h.buffer.asUint8List());body.add(data);final c=ByteData(46+name.length);c.setUint32(0,0x02014b50,Endian.little);c.setUint16(4,20,Endian.little);c.setUint16(6,20,Endian.little);c.setUint16(8,0x800,Endian.little);c.setUint32(16,checksum,Endian.little);c.setUint32(20,data.length,Endian.little);c.setUint32(24,data.length,Endian.little);c.setUint16(28,name.length,Endian.little);c.setUint32(42,offset,Endian.little);c.buffer.asUint8List().setRange(46,46+name.length,name);central.add(c.buffer.asUint8List());offset+=h.lengthInBytes+data.length;}final end=ByteData(22);end.setUint32(0,0x06054b50,Endian.little);end.setUint16(8,files.length,Endian.little);end.setUint16(10,files.length,Endian.little);end.setUint32(12,central.length,Endian.little);end.setUint32(16,offset,Endian.little);body.add(central.takeBytes());body.add(end.buffer.asUint8List());return body.takeBytes();
}
class _AudioPreview extends StatefulWidget {
  const _AudioPreview({required this.url});
  final String url;
  @override State<_AudioPreview> createState()=>_AudioPreviewState();
}
class _AudioPreviewState extends State<_AudioPreview> {
  final player=AudioPlayer();StreamSubscription<PlayerState>? subscription;bool playing=false;
  @override void initState(){super.initState();subscription=player.onPlayerStateChanged.listen((state){if(mounted)setState(()=>playing=state==PlayerState.playing);});}
  @override void dispose(){unawaited(subscription?.cancel());unawaited(player.dispose());super.dispose();}
  @override Widget build(BuildContext context)=>OutlinedButton.icon(icon:Icon(playing?Icons.pause:Icons.play_arrow),label:Text(playing?'녹음 일시정지':'녹음 원본 재생'),onPressed:()async{try{if(playing){await player.pause();return;}final uri=Uri.tryParse(widget.url);if(uri==null||!['https','http','data'].contains(uri.scheme))throw StateError('재생 가능한 녹음 주소가 없습니다.');if(uri.scheme=='data'){final data=UriData.fromUri(uri);await player.play(BytesSource(data.contentAsBytes()));}else{await player.play(UrlSource(widget.url));}}catch(_){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('녹음을 재생하지 못했습니다. 파일 주소·연결 상태를 확인해 주세요.')));}});
}
